         const accessToken = await accessTokens.findOne({ email: user.email });

         await client.close();

         if (!accessToken) {
           // User does not have a saved access token, log out
           setUser(null);
         } else {
           // Check if the access token is still valid
           const response = await fetch(`https://www.googleapis.com/oauth2/v3/tokeninfo?id_token=${accessToken.token}`);
           if (!response.ok) {
             // Access token is no longer valid, log out
             setUser(null);
           }
         }
       }

       if (user) {
         checkAccessToken();

         // Set up a timer to check the access token every 5 minutes
         const timerId = setInterval(checkAccessToken, 5 * 60 * 1000);

         return () => clearInterval(timerId);
       }
     }, [user]);

     function handleLogin(userData) {
       setUser(userData);
     }

     return (
       <div>
         {user ? (
           <div>
             <p>Welcome, {user.name} ({user.email})!</p>
             <p>Your access token is: {user.token}</p>
           </div>
         ) : (
           <Login onLogin={handleLogin} />
         )}
       </div>
     );
   }

   export default App;
```
This component uses the `useEffect` hook to periodically check if the user's access token is still valid. If the token is no longer valid, the component logs the user out by setting `user` to `null`.

