```csharp
using OpenCvSharp;
using System;
using System.Linq;

public static class ImageRotationUtility
{
    public static double GetRotateAngle(string filename, double fixedWidth = 300.0)
    {
        Mat img = Cv2.ImRead(filename, ImreadModes.Color);
        var (height, width, _) = img.Shape;

        double scale = fixedWidth / width;
        width *= scale;
        height *= scale;

        var resizeImg = new Mat();
        Cv2.Resize(img, resizeImg, new Size((int)width, (int)height));

        var blurImg = new Mat();
        Cv2.GaussianBlur(resizeImg, blurImg, new Size(3, 3), 0, 0, BorderTypes.Default);

        var grayImg = new Mat();
        Cv2.CvtColor(blurImg, grayImg, ColorConversionCodes.BGR2GRAY);

        var thresholdImg = new Mat();
        Cv2.AdaptiveThreshold(grayImg, thresholdImg, 255, AdaptiveThresholdTypes.GaussianC, ThresholdTypes.BinaryInv, 5, 10);

        double delta = 1;
        int limit = 45;
        var angles = Enumerable.Range(-limit, limit * 2 + 1).Select(x => x * delta).ToArray();
        var scores = new double[angles.Length];
        for (int i = 0; i < angles.Length; i++)
        {
            var (hist, score) = FindScore(thresholdImg, angles[i]);
            scores[i] = score;
        }

        double bestScore = scores.Max();
        double bestAngle = angles[scores.ToList().IndexOf(bestScore)];

        return bestAngle;
    }

    private static (Mat, double) FindScore(Mat img, double angle)
    {
        var rotMat = Cv2.GetRotationMatrix2D(new Point2f((float)img.Cols / 2, (float)img.Rows / 2), angle, 1);
        var rotatedImg = new Mat();
        Cv2.WarpAffine(img, rotatedImg, rotMat, img.Size, InterpolationFlags.Linear, BorderTypes.Constant, Scalar.All(255));

        var hist = new Mat();
        var mask = new Mat();
        var channel = new MatOfInt(0);
        var hSize = new MatOfInt(180);
        var hueRange = new Rangef(0, 180);
        var maskVal = new Scalar(255, 0, 0);
        var histRange = new Rangef(0, 180);

        mask.SetTo(maskVal);
        Cv2.CalcHist(new[] { rotatedImg }, new[] { channel }, mask, hist, new[] { hSize }, new[] { histRange });

        var minVal = 0.0;
        var maxVal = 0.0;
        Cv2.MinMaxLoc(hist, out minVal, out maxVal);

        return (hist, maxVal);
    }
}
