public static Tuple<int, double> FindScore(int[,] arr, int angle)
{
    int[,] data = RotateImage(arr, angle);
    int[] hist = new int[arr.GetLength(0)];
    for (int i = 0; i < data.GetLength(0); i++)
    {
        for (int j = 0; j < data.GetLength(1); j++)
        {
            hist[i] += data[i, j];
        }
    }
    double score = 0;
    for (int i = 1; i < hist.Length; i++)
    {
        score += Math.Pow(hist[i] - hist[i - 1], 2);
    }
    return Tuple.Create(angle, score);
}

public static int[,] RotateImage(int[,] image, int angle)
{
    double radians = (Math.PI / 180) * angle;
    double sin = Math.Sin(radians);
    double cos = Math.Cos(radians);
    double width = image.GetLength(1);
    double height = image.GetLength(0);
    double newWidth = (Math.Abs(sin) * height) + (Math.Abs(cos) * width);
    double newHeight = (Math.Abs(cos) * height) + (Math.Abs(sin) * width);
    int[,] result = new int[(int)newHeight, (int)newWidth];
    for (int x = 0; x < newWidth; x++)
    {
        for (int y = 0; y < newHeight; y++)
        {
            int centerX = (int)(width / 2);
            int centerY = (int)(height / 2);
            int u = (int)(((x - newWidth / 2) * cos) + ((y - newHeight / 2) * sin) + centerX);
            int v = (int)(((y - newHeight / 2) * cos) - ((x - newWidth / 2) * sin) + centerY);
            if (u >= 0 && u < width && v >= 0 && v < height)
            {
                result[y, x] = image[v, u];
            }
        }
    }
    return result;
}

