using System;
using OpenCvSharp;
using OpenCvSharp.Extensions;
using System.Linq;

public static class ImageUtils
{
    public static (Mat Hist, double Score) FindScore(Mat arr, double angle)
    {
        var rotationMat = Cv2.GetRotationMatrix2D(center: new Point2f(arr.Width / 2f, arr.Height / 2f), angle, 1.0);
        var data = arr.WarpAffine(rotationMat, arr.Size(), InterpolationFlags.Cubic, BorderTypes.Constant, Scalar.All(255));
        var hist = data.RowRange(0, data.Rows).Reduce(ReductionOp.SUM, -1);
        var score = Cv2.Pow(hist[1..] - hist[..^1], 2).Sum();
        return (hist, score);
    }

    public static double GetRotateAngle(string filename, double fixedWidth = 300.0)
    {
        var img = Cv2.ImRead(filename);
        var (height, width, _) = img.Shape;
        var scale = fixedWidth / width;
        width *= scale;
        height *= scale;

        var resizeImg = img.Resize(new Size((int)width, (int)height));
        var blurImg = resizeImg.GaussianBlur(new Size(3, 3), 0);
        var grayImg = blurImg.CvtColor(ColorConversionCodes.BGR2GRAY);
        var thresholdImg = grayImg.AdaptiveThreshold(255, AdaptiveThresholdTypes.GaussianC, ThresholdTypes.BinaryInv, 5, 10);

        var delta = 1;
        var limit = 45;
        var angles = Enumerable.Range(-limit, 2 * limit / delta + 1).Select(i => i * delta);
        var scores = angles.Select(angle => FindScore(thresholdImg, angle).Score);

        var bestScore = scores.Max();
        var bestAngle = angles.ElementAt(scores.ToList().IndexOf(bestScore));

        return bestAngle;
    }
}
