As you mentioned, the `Bitmap` class in C# does not have a built-in `Blur` method. However, you can implement a Gaussian blur filter using convolution matrices. Here's an updated code that uses convolution to apply a Gaussian blur to a `Bitmap` object:
```scss
public static Bitmap ApplyGaussianBlur(Bitmap image, int radius)
{
    if (radius < 1)
        throw new ArgumentException("Invalid radius");

    int size = radius * 2 + 1;
    float[,] matrix = new float[size, size];
    float sigma = radius / 3.0f;
    float twoSigmaSquared = 2 * sigma * sigma;
    float total = 0.0f;

    for (int x = -radius; x <= radius; x++)
    {
        for (int y = -radius; y <= radius; y++)
        {
            float distance = (x * x + y * y) / twoSigmaSquared;
            matrix[x + radius, y + radius] = (float)Math.Exp(-distance);
            total += matrix[x + radius, y + radius];
        }
    }

    for (int x = 0; x < size; x++)
    {
        for (int y = 0; y < size; y++)
        {
            matrix[x, y] /= total;
        }
    }

    Bitmap result = new Bitmap(image.Width, image.Height);

    for (int x = radius; x < image.Width - radius; x++)
    {
        for (int y = radius; y < image.Height - radius; y++)
        {
            float r = 0.0f, g = 0.0f, b = 0.0f;

            for (int i = -radius; i <= radius; i++)
            {
                for (int j = -radius; j <= radius; j++)
                {
                    Color pixel = image.GetPixel(x + i, y + j);
                    float weight = matrix[i + radius, j + radius];

                    r += pixel.R * weight;
                    g += pixel.G * weight;
                    b += pixel.B * weight;
                }
            }

            r = Math.Min(255, Math.Max(0, r));
            g = Math.Min(255, Math.Max(0, g));
            b = Math.Min(255, Math.Max(0, b));

            Color newColor = Color.FromArgb((int)r, (int)g, (int)b);
            result.SetPixel(x, y, newColor);
        }
    }

    return result;
}
```
