public static Tuple FindScore(Bitmap arr, int angle)
 {
 Bitmap data = RotateImage(arr, angle);
 int[] hist = new int[data.Height];
 for (int y = 0; y < data.Height; y++)
 {
 for (int x = 0; x < data.Width; x++)
 {
 Color color = data.GetPixel(x, y);
 int pixel = color.R;
 hist[y] += pixel;
 }
 }
 int score = 0;
 for (int i = 1; i < hist.Length; i++)
