```csharp
public static Bitmap AdaptiveThreshold(Bitmap input, int blockSize, int c, double stdDev = 1.0)
{
    // Create a grayscale image
    Bitmap gray = Grayscale(input);

    // Apply GaussianBlur to reduce noise
    Bitmap blur = GaussianBlur(gray, stdDev);

    // Initialize output image
    Bitmap output = new Bitmap(input.Width, input.Height);

    // Iterate through each pixel
    for (int y = 0; y < input.Height; y++)
    {
        for (int x = 0; x < input.Width; x++)
        {
            // Calculate the threshold value for the current block
            double blockThreshold = GaussianWeightedAverage(blur, x, y, blockSize) - c;

            // Check if the current pixel is greater than or equal to the threshold value
            Color color = input.GetPixel(x, y);
            int pixel = color.R;
            int value = pixel >= blockThreshold ? 255 : 0;

            // Set the pixel value in the output image
            Color newColor = Color.FromArgb(value, value, value);
            output.SetPixel(x, y, newColor);
        }
    }

    return output;
}
