아래는 C#에서 Bitmap 객체에 Gaussian Blur를 적용하는 예시 코드입니다. 이 코드에서는 이미지의 테두리에 대해서는 처리하지 않고, 간단한 버전의 Gaussian Blur를 적용하도록 하였습니다.
```csharp
private static Bitmap GaussianBlur(Bitmap image, double sigma)
{
    int radius = (int)Math.Ceiling(sigma * 3);
    int width = image.Width;
    int height = image.Height;

    Bitmap output = new Bitmap(width, height);

    // Calculate Gaussian kernel
    double[,] kernel = new double[radius * 2 + 1, radius * 2 + 1];
    double kernelSum = 0;
    for (int j = -radius; j <= radius; j++)
    {
        for (int i = -radius; i <= radius; i++)
        {
            double weight = Math.Exp(-(i * i + j * j) / (2 * sigma * sigma));
            kernel[i + radius, j + radius] = weight;
            kernelSum += weight;
        }
    }

    // Normalize Gaussian kernel
    for (int j = -radius; j <= radius; j++)
    {
        for (int i = -radius; i <= radius; i++)
        {
            kernel[i + radius, j + radius] /= kernelSum;
        }
    }

    // Apply Gaussian blur
    for (int y = 0; y < height; y++)
    {
        for (int x = 0; x < width; x++)
        {
            double sumR = 0, sumG = 0, sumB = 0, weightSum = 0;

            for (int j = -radius; j <= radius; j++)
            {
                for (int i = -radius; i <= radius; i++)
                {
                    int pixelX = x + i;
                    int pixelY = y + j;

                    if (pixelX >= 0 && pixelX < width && pixelY >= 0 && pixelY < height)
                    {
                        Color pixelColor = image.GetPixel(pixelX, pixelY);
                        double weight = kernel[i + radius, j + radius];
                        sumR += weight * pixelColor.R;
                        sumG += weight * pixelColor.G;
                        sumB += weight * pixelColor.B;
                        weightSum += weight;
                    }
                }
            }

            int outputR = (int)Math.Round(sumR / weightSum);
            int outputG = (int)Math.Round(sumG / weightSum);
            int outputB = (int)Math.Round(sumB / weightSum);
            output.SetPixel(x, y, Color.FromArgb(outputR, outputG, outputB));
        }
    }

    return output;
}
```
Gaussian kernel을 생성하는 부분에서 테두리 처리 방법을 변경하면, 테두리에 대해서도 적절하게 처리할 수 있습니다.
다음 코드를 효율적으로 리팩토링 해줘

 public static Bitmap RotateImage(Bitmap image, float angle)
 {
 angle = angle \* (float)Math.PI / 180f;

 int width = (int)Math.Round(image.Width \* Math.Abs(Math.Cos(angle)) + image.Height \* Math.Abs(Math.Sin(angle)));
 int height = (int)Math.Round(image.Height \* Math.Abs(Math.Cos(angle)) + image.Width \* Math.Abs(Math.Sin(angle)));
 Bitmap rotatedImage = new Bitmap(width, height);
 using (Graphics g = Graphics.FromImage(rotatedImage))
 {
 g.TranslateTransform(width / 2, height / 2);
 g.RotateTransform(angle \* 180f / (float)Math.PI);
 g.TranslateTransform(-image.Width / 2, -image.Height / 2);
 g.DrawImage(image, new Point(0, 0));
 }

 return rotatedImage;
 }
아래는 RotateImage 함수의 리팩토링된 버전입니다. 주요 변경 사항은 다음과 같습니다.

* Math.Abs 대신 MathF.Abs 사용
* Math.Round 대신 MathF.Round 사용
* Graphics 객체의 생성과 해제를 using 문으로 감싸기
* Graphics 객체를 통해 직접 이미지를 회전시키는 대신, GraphicsPath 객체를 사용하여 이미지를 회전시키기
* GraphicsPath 객체를 통해 회전된 이미지를 그리는 대신, Graphics 객체의 DrawImage 메서드의 좌표 매개변수를 이용하여 이미지를 그리기
```csharp
public static Bitmap RotateImage(Bitmap image, float angle)
{
    angle = angle * MathF.PI / 180f;

    int width = (int)MathF.Round(image.Width * MathF.Abs(MathF.Cos(angle)) + image.Height * MathF.Abs(MathF.Sin(angle)));
    int height = (int)MathF.Round(image.Height * MathF.Abs(MathF.Cos(angle)) + image.Width * MathF.Abs(MathF.Sin(angle)));

    Bitmap rotatedImage = new Bitmap(width, height);
    using (Graphics g = Graphics.FromImage(rotatedImage))
    {
        g.Clear(Color.White);

        using (GraphicsPath path = new GraphicsPath())
        {
            PointF center = new PointF(width / 2f, height / 2f);
            path.AddRectangle(new RectangleF(PointF.Empty, new SizeF(image.Width, image.Height)));
            path.RotateAt(angle * 180f / MathF.PI, center);

            g.DrawImage(image, new PointF(0, 0));
        }
    }

    return rotatedImage;
}
```
위의 코드는 이미지 회전을 좀 더 효율적으로 수행할 수 있으며, 가독성도 좋아졌습니다. 또한, `Clear` 메서드를 사용하여 회전된 이미지의 배경색을 흰색으로 지정하여 새로운 이미지의 픽셀이 투명하지 않도록 했습니다.
