public static long FindScore(Bitmap image, int angle)
{
    Bitmap rotatedImage = RotateImage(image, angle);
    int height = rotatedImage.Height;
    int width = rotatedImage.Width;
    long score = 0;

    int[] hist = new int[height];
    for (int y = 0; y < height; y++)
    {
        int pixelSum = 0;
        for (int x = 0; x < width; x++)
        {
            Color color = rotatedImage.GetPixel(x, y);
            pixelSum += (int)(0.299 * color.R + 0.587 * color.G + 0.114 * color.B);
        }
        hist[y] = pixelSum;
    }

    for (int i = 1; i < hist.Length; i++)
    {
        int diff = hist[i] - hist[i - 1];
        score += diff * diff;
    }
    return score;
