```csharp
public static int GetRotateAngle(Bitmap img, double fixedWidth = 300.0)
{
    int height = img.Height;
    int width = img.Width;

    double scale = (double)fixedWidth / width;
    width = (int)(width * scale);
    height = (int)(height * scale);

    Bitmap resizeImg = new Bitmap(img, new Size(width, height));
    Bitmap thresholdImg = AdaptiveThreshold(resizeImg, 255, 5, 10);

    int delta = 1;
    int limit = 45;
    int numThreads = Environment.ProcessorCount;
    long[] angles = new long[2 * limit / delta + 1];

    Parallel.For(0, numThreads, threadIndex =>
    {
        int start = threadIndex * angles.Length / numThreads;
        int end = (threadIndex + 1) * angles.Length / numThreads;

        for (int i = start; i < end; i++)
        {
            int angle = i * delta - limit;
            angles[i] = FindScore(thresholdImg, angle);
        }
    });

    long bestScore = angles.Max();
    int bestAngle = Array.IndexOf(angles, bestScore) * delta - limit;

    resizeImg.Dispose();
    thresholdImg.Dispose();
    return bestAngle;
}
