  const mqlValues = mqlRange.getValues();
  const mqlBackgrounds = mqlRange.getBackgrounds();

  const processedColor = '#999999';

  for (let i = 0; i < lastRow; i++) {
    if (mqlValues[i][0] === true && mqlBackgrounds[i][0] !== processedColor) {
      const rowData = sumSheet.getRange(i + 1, 1, 1, sumSheet.getLastColumn()).getValues();
      const firstEmptyRow = bdLeadsSheet.getLastRow() + 1;
      bdLeadsSheet.getRange(firstEmptyRow, 1, 1, rowData[0].length).setValues(rowData);

