以下是一個根據您需求編寫的 Google Apps Script：
```javascript
function sendMQLToBDLeads() {
  const sumSheetName = 'SUM';
  const bdLeadsSheetName = 'BD_Leads';
  const mqlColumn = 26; // Z 欄
  const idColumn = 27; // AA 欄
  const bdLeadsIdColumn = 19; // S 欄

  const activeSpreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  const sumSheet = activeSpreadsheet.getSheetByName(sumSheetName);
  const bdLeadsSheet = activeSpreadsheet.getSheetByName(bdLeadsSheetName);

  const lastRow = sumSheet.getLastRow();
  const mqlValues = sumSheet.getRange(1, mqlColumn, lastRow).getValues();

  for (let i = 0; i < lastRow; i++) {
    const mqlValue = mqlValues[i][0];
    const sumIdValue = sumSheet.getRange(i + 1, idColumn).getValue();
    const bdLeadsData = bdLeadsSheet.getRange(1, bdLeadsIdColumn, bdLeadsSheet.getLastRow()).getValues();

    if (mqlValue === true && !sumIdValue) {
      const rowData = sumSheet.getRange(i + 1, 1, 1, sumSheet.getLastColumn()).getValues();
      const firstEmptyRow = bdLeadsSheet.getLastRow() + 1;
      bdLeadsSheet.getRange(firstEmptyRow, 1, 1, rowData[0].length).setValues(rowData);

      const uniqueId = `ID-${new Date().getTime()}`;
      sumSheet.getRange(i + 1, idColumn).setValue(uniqueId);
      bdLeadsSheet.getRange(firstEmptyRow, bdLeadsIdColumn).setValue(uniqueId);
    } else if (mqlValue === false && sumIdValue) {
      const index = bdLeadsData.findIndex(row => row[0] === sumIdValue);
      if (index !== -1) {
        bdLeadsSheet.deleteRow(index + 1);
        sumSheet.getRange(i + 1, idColumn).setValue('');
      }
    }
