function runOnTrigger() {
  const sheetName = "SUM";
  const bdLeadsSheetName = "BD_Leads";
  const mqlColumn = 26;
  const idColumnSumSheet = 27;
  const idColumnBDLeadsSheet = 21;

  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheetName);
