  for (let row = 2; row <= numRows; row++) {
    const cell = sheet.getRange(row, mqlColumn);
    const e = {
      range: cell,
      source: SpreadsheetApp.getActiveSpreadsheet()
    };
    onEdit(e);
  }
}
