can you add pages to the sales order search and show more than 1000 search results
Yes, you can add paging to the sales order search and retrieve more than 1000 search results using SuiteScript 2.0.

To add paging to the search, you can use the `search.runPaged(options)` method instead of `search.run()`. The `options` parameter should include the following properties:

* `pageSize`: The maximum number of search results to retrieve in each page.
* `returnFullResultSet`: A Boolean value indicating whether to return the full result set or just a subset. Set this to `true` to return the full result set.
* `pageIndex`: The index of the page to retrieve. The first page has an index of 0.

Here's an updated version of the script that includes paging:
```javascript
/**
 * @NApiVersion 2.x
 * @NScriptType Suitelet
 * @NModuleScope SameAccount
 */
define(['N/ui/serverWidget', 'N/search'], function(ui, search) {
  function onRequest(context) {
    if (context.request.method === 'GET') {
      var form = ui.createForm({
        title: 'Sales Order Search'
      });

      var customerGroupField = form.addField({
        id: 'customergroup',
        type: ui.FieldType.SELECT,
        label: 'Customer Group',
        source: 'customlist_customer_group'
      });

      var submitButton = form.addSubmitButton({
        label: 'Search'
      });

      context.response.writePage(form);
    } else {
      var customerGroupId = context.request.parameters.customergroup;

      var salesOrderSearch = search.create({
        type: search.Type.SALES_ORDER,
        columns: ['tranid', 'entity', 'total'],
        filters: [
          ['custbody_customer_group', 'anyof', customerGroupId]
        ],
        pageSize: 1000,
        returnFullResultSet: true
      });

      var page = 0;
      var maxPages = 10; // Set a maximum of 10 pages

      do {
        var salesOrders = salesOrderSearch.runPaged({
          pageIndex: page
        });

        salesOrders.pageRanges.forEach(function(pageRange) {
          var currentPageSalesOrders = salesOrders.fetch({
            index: pageRange.index
          }).data;

          currentPageSalesOrders.forEach(function(salesOrder) {
            log.debug({
              title: 'Sales Order',
              details: 'ID: ' + salesOrder.getValue('tranid') + ', Customer: ' + salesOrder.getText('entity') + ', Total: ' + salesOrder.getValue('total')
            });
          });
        });

        page++;
      } while (salesOrders.pageRanges.length > 0 && page < maxPages);

      context.response.write('Search completed.');
    }
  }

  return {
    onRequest: onRequest
  };
});
```
In this example, we've added a `do...while` loop that retrieves each page of search results using `salesOrderSearch.runPaged()` and iterates over each sales order on the page to log its ID, customer, and total. The loop continues until there are no more pages or until the maximum number of pages (10 in this example) has been reached.

Note that the maximum page size is 1000, so if you want to retrieve more than 1000 search results, you'll need to use paging as shown in this example.
