# Use cosine similarity to find properties similar to a user's search query
def search(query):
    query_tfidf = tfidf.transform([query])
    similarity_scores = cosine_similarity(query_tfidf, tfidf_matrix)
    results = df.iloc[similarity_scores[0].argsort()[::-1]]
    return results

