```javascript
window.addEventListener('load', function() {
  var viewIn3DButton = document.querySelector('#view-in-3d-button');
  var modelViewerOverlay = document.querySelector('#model-viewer-overlay');
  var modelViewer = document.querySelector('model-viewer');
