        else if (item is XmlSchemaComplexType complexType && filteredElements.Any(name => complexType.QualifiedName.Name.StartsWith(name)))
        {
            typeNames.Add(complexType.QualifiedName.Name);
            AddComplexTypeAndDependencies(complexType, originalSchema, typeNames);
        }
    }

    foreach (var typeName in typeNames)
    {
        var type = originalSchema.Items.OfType<XmlSchemaComplexType>().FirstOrDefault(t => t.QualifiedName.Name == typeName);
        if (type != null)
        {
            filteredSchema.Items.Add(type);
        }
    }

    filteredSchemaSet.Add(filteredSchema);
    filteredSchemaSet.Compile();
    return filteredSchemaSet;
}

private void AddComplexTypeAndDependencies(XmlSchemaComplexType complexType, XmlSchema originalSchema, HashSet<string> typeNames)
{
    if (complexType.ContentTypeParticle is XmlSchemaParticle particle)
    {
        AddParticleDependencies(particle, originalSchema, typeNames);
    }
}

private void AddParticleDependencies(XmlSchemaParticle particle, XmlSchema originalSchema, HashSet<string> typeNames)
{
    if (particle is XmlSchemaElement element)
    {
        if (element.ElementSchemaType is XmlSchemaComplexType complexType && !typeNames.Contains(complexType.QualifiedName.Name))
        {
            typeNames.Add(complexType.QualifiedName.Name);
            AddComplexTypeAndDependencies(complexType, originalSchema, typeNames);
        }
    }
    else if (particle is XmlSchemaGroupBase groupBase)
    {
        foreach (var groupParticle in groupBase.Items.OfType<XmlSchemaParticle>())
        {
            AddParticleDependencies(groupParticle, originalSchema, typeNames);
        }
    }
}
