```javascript
const todoList = document.querySelector('.todo-list');
const todoForm = document.querySelector('.todo-form');
const todoInput = document.querySelector('.todo-input');

let todos = [];

function renderTodoList() {
  let html = '';
  todos.forEach((todo, index) => {
    html += `
      <div class="todo-item">
        <input type="checkbox" ${todo.completed ? 'checked' : ''} onchange="toggleComplete(${index})">
        <span class="todo-title ${todo.completed ? 'completed' : ''}">${todo.title}</span>
        <button class="delete-btn" onclick="deleteTodo(${index})">Delete</button>
      </div>
    `;
  });
  todoList.innerHTML = html;
}

function addTodo() {
  const title = todoInput.value.trim();
  if (title) {
    todos.push({ title, completed: false });
    renderTodoList();
    todoInput.value = '';
  }
}

function toggleComplete(index) {
  todos[index].completed = !todos[index].completed;
  renderTodoList();
}

function deleteTodo(index) {
  todos.splice(index, 1);
  renderTodoList();
}

todoForm.addEventListener('submit', (event) => {
  event.preventDefault();
  addTodo();
});

renderTodoList();
```
此範例使用 `querySelector` 方法選取 DOM 元素，並使用 `innerHTML` 屬性來動態更新 HTML。在代辦事項新增、完成與刪除時，也是直接操作 `todos` 陣列的資料，並呼叫 `renderTodoList` 方法重新渲染整個代辦清單。
